{"code":"function chooseBin(item, remainingCapacities) {
  const n = remainingCapacities.length;
  let best = -1, bestRem = 101;
  for (let i = 0; i < n; i++) {
    const r = remainingCapacities[i];
    if (r >= item && r < bestRem) {
      best = i;
      bestRem = r;
      if (r === item) break;
    }
  }
  return best;
}","hypothesis":"Adding an early-exit when a perfect-fit bin is found reduces scan time without changing behavior, and the current bestFit is already optimal for this distribution."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestRem = 101;
  for (let i = 0; i < remainingCapacities.length; i++) {
    const r = remainingCapacities[i];
    if (r >= item && r < bestRem) { bestRem = r; best = i; }
  }
  return best;
}","hypothesis":"Cache bestRem across iterations to skip recomputing array lookups and short-circuit earlier on exact-fit candidates."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestRem = 101;
  for (let i = 0; i < remainingCapacities.length; i++) {
    const r = remainingCapacities[i];
    if (r >= item) {
      if (r < bestRem) {
        bestRem = r;
        best = i;
      } else if (r === bestRem && r - item > (remainingCapacities[best] - item)) {
        best = i;
      }
    }
  }
  if (best === -1) return -1;
  const slack = remainingCapacities[best] - item;
  if (slack >= 60) return -1;
  if (slack >= 40 && item <= 30) return -1;
  return best;
}","hypothesis":"Avoid Best-Fit when leftover slack exceeds 60 (or 40 with item≤30); exact-fit preferred, else tightest fit."}

