{"code":"function chooseBin(item, remainingCapacities) {
  const n = remainingCapacities.length;
  let best = -1;
  for (let i = 0; i < n; i++) {
    if (remainingCapacities[i] >= item && (best === -1 || remainingCapacities[i] < remainingCapacities[best])) best = i;
  }
  if (best === -1) return -1;
  // Threshold: for large items in an already-populated pack, consider Best Fit with leftover slack penalty
  if (item >= 40 && n >= 4) {
    let alt = -1;
    let altScore = Infinity;
    for (let i = 0; i < n; i++) {
      if (remainingCapacities[i] >= item) {
        const slack = remainingCapacities[i] - item;
        // Penalize slack: prefer tighter fits, but also consider not filling if slack > 30
        const score = slack + (slack > 30 ? slack * 0.5 : 0);
        if (score < altScore) { altScore = score; alt = i; }
      }
    }
    if (alt !== -1 && altScore < (remainingCapacities[best] - item)) best = alt;
  }
  return best;
}","hypothesis":"For items >=40 when >=4 bins exist, prefer Best-Fit with slack penalty >30 to avoid wasting capacity in nearly-empty bins, improving mean bin count."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestScore = Infinity;
  for (let i = 0; i < remainingCapacities.length; i++) {
    const r = remainingCapacities[i];
    if (r < item) continue;
    const left = r - item;
    let score;
    if (left >= item) score = left;
    else if (left >= item / 2) score = 200 + left;
    else score = 400 + left;
    if (score < bestScore) { bestScore = score; best = i; }
  }
  return best;
}","hypothesis":"When two bins can hold the same item, prefer keeping one that can still fit another copy of item; this halves bins on repeated-size tails."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestSlack = Infinity;
  let n = remainingCapacities.length;
  if (n === 0) return -1;
  // Threshold for very small residual fragments: opening a new bin is cheaper than wasting a usable slot.
  if (item <= 12 && n > 1) {
    let tightCount = 0;
    let tightBest = -1;
    let tightSlack = Infinity;
    for (let i = 0; i < n; i++) {
      let r = remainingCapacities[i];
      if (r >= item) {
        tightCount++;
        if (r - item < tightSlack) {
          tightSlack = r - item;
          tightBest = i;
        }
      }
    }
    // If at least 2 bins can still host this item, do NOT consume a near-full bin: open a new one.
    if (tightCount >= 2) return -1;
    if (tightCount === 1) return tightBest;
  }
  for (let i = 0; i < n; i++) {
    let r = remainingCapacities[i];
    let slack = r - item;
    if (slack >= 0 && slack < bestSlack) {
      bestSlack = slack;
      best = i;
    }
  }
  return best;
}","hypothesis":"Avoid best-fit for small items (≤12) when 2+ bins could still hold them; open a new bin instead so tight bins keep their residual capacity for larger later items."}

