{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestSlack = Infinity;
  let secondBestSlack = Infinity;
  const n = remainingCapacities.length;
  for (let i = 0; i < n; i++) {
    const c = remainingCapacities[i];
    if (c >= item) {
      const slack = c - item;
      if (slack < bestSlack) {
        secondBestSlack = bestSlack;
        bestSlack = slack;
        best = i;
      } else if (slack < secondBestSlack) {
        secondBestSlack = slack;
      }
    }
  }
  if (best !== -1 && bestSlack <= 30 && secondBestSlack - bestSlack <= 15) {
    let newBinNeeded = true;
    for (let i = 0; i < n; i++) {
      if (i !== best && remainingCapacities[i] >= item && remainingCapacities[i] - item <= bestSlack + 25) {
        newBinNeeded = false;
        break;
      }
    }
    if (newBinNeeded) return best;
  }
  if (best !== -1 && bestSlack > 60) return best;
  if (best !== -1 && bestSlack <= 20) return -1;
  return best;
}","hypothesis":"Avoid tight Best-Fit fits when no comparable alternative exists; opening a new bin for medium items prevents residual small gaps that Best-Fit alone accumulates."}

{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestRem = 101;
  let bestW = 0;
  for (let i = 0; i < remainingCapacities.length; i++) {
    const r = remainingCapacities[i];
    if (r >= item) {
      const w = r - item;
      if (w === 0) return i;
      const tight = r * 100 + w;
      if (tight < bestW || best === -1) { bestW = tight; bestRem = r; best = i; }
    }
  }
  return best;
}","hypothesis":"Break exact-fit ties by absolute remaining capacity, preferring tighter bins to leave room for larger later items."}

{"code":"function chooseBin(item, remainingCapacities) {
  const n = remainingCapacities.length;
  let best = -1;
  let bestSlack = Infinity;
  for (let i = 0; i < n; i++) {
    if (remainingCapacities[i] >= item) {
      const slack = remainingCapacities[i] - item;
      if (slack < bestSlack) { bestSlack = slack; best = i; }
    }
  }
  if (best === -1) return -1;
  // Worst-fit: if many bins exist and the best fit leaves large slack, prefer fuller bin
  if (n >= 6 && item >= 30 && bestSlack >= 30) {
    let worst = -1;
    let worstCap = -Infinity;
    for (let i = 0; i < n; i++) {
      if (remainingCapacities[i] >= item && remainingCapacities[i] > worstCap) {
        worstCap = remainingCapacities[i]; worst = i;
      }
    }
    if (worst !== -1 && worstCap >= 60) return worst;
  }
  // Small items: prefer tight fits to leave room for large items
  if (item <= 15 && n >= 4) {
    let tight = -1;
    let tightSlack = Infinity;
    for (let i = 0; i < n; i++) {
      if (remainingCapacities[i] >= item) {
        const slack = remainingCapacities[i] - item;
        if (slack < tightSlack) { tightSlack = slack; tight = i; }
      }
    }
    if (tight !== -1 && tightSlack <= 10) return tight;
  }
  return best;
}","hypothesis":"For items >=30 in >=6 bins where best-fit slack >=30, place in fullest qualifying bin (worst-fit) to consolidate large items and reduce bin count."}

