      bestWaste = w;
      bestRem = r;
      best = i;
    }
  }
  return best;
}","hypothesis":"When ≤1 bin can fit the item, penalize waste > item heavily to avoid large gaps; otherwise stay near Best-Fit with mild fuller-bin preference."}

